/* ============================================================
   JEPRETIN — Auth & Photo History (client-side only)
   ------------------------------------------------------------
   Semua data (akun, sesi, riwayat foto) disimpan di localStorage
   browser ini saja. Tidak ada server, jadi ini BUKAN sistem login
   yang aman untuk data sensitif — cukup untuk personalisasi &
   riwayat foto per-perangkat pada kiosk/demo.
   ============================================================ */
(function () {
  const USERS_KEY = 'jepretin_users_v1';
  const SESSION_KEY = 'jepretin_session_v1';
  const HISTORY_KEY = 'jepretin_history_v1';
  const MAX_HISTORY_PER_USER = 24;
  const USERNAME_RE = /^[a-zA-Z0-9_]{3,16}$/;

  // Logo icon di-embed sebagai data URI (bukan file terpisah) supaya canvas
  // #mockup-canvas TIDAK pernah "tainted" oleh gambar lintas-asal/lokal —
  // ini yang bikin tombol Unduh POV gagal diam-diam saat project dibuka
  // langsung dari file:// (tanpa server), karena canvas.toDataURL() menolak
  // meng-export canvas yang sudah tainted.
  const JEPRETIN_ICON_DATA_URI = 'data:image/png;base64,';

  /* ---------------- storage helpers ---------------- */
  function readJSON(key, fallback) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch (e) { return fallback; }
  }
  function writeJSON(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch (e) { return false; }
  }
  function getUsers() { return readJSON(USERS_KEY, {}); }
  function getHistoryStore() { return readJSON(HISTORY_KEY, {}); }

  /* ---------------- crypto helpers ---------------- */
  function toHex(buffer) {
    return Array.from(new Uint8Array(buffer)).map(b => b.toString(16).padStart(2, '0')).join('');
  }
  function randomSaltHex() {
    const arr = new Uint8Array(16);
    crypto.getRandomValues(arr);
    return toHex(arr.buffer);
  }
  async function hashPassword(password, saltHex) {
    const enc = new TextEncoder();
    const data = enc.encode(saltHex + ':' + password);
    const digest = await crypto.subtle.digest('SHA-256', data);
    return toHex(digest);
  }

  /* ---------------- session ---------------- */
  function getCurrentUserKey() {
    return localStorage.getItem(SESSION_KEY) || null;
  }
  function getCurrentUser() {
    const key = getCurrentUserKey();
    if (!key) return null;
    const users = getUsers();
    return users[key] || null;
  }
  function isLoggedIn() { return !!getCurrentUserKey(); }

  /* ---------------- register / login / logout ---------------- */
  async function registerUser(usernameRaw, password, passwordConfirm) {
    const username = (usernameRaw || '').trim();
    if (!USERNAME_RE.test(username)) {
      return { ok: false, error: 'Username 3-16 karakter, huruf/angka/underscore saja.' };
    }
    if (!password || password.length < 4) {
      return { ok: false, error: 'Kata sandi minimal 4 karakter.' };
    }
    if (password !== passwordConfirm) {
      return { ok: false, error: 'Konfirmasi kata sandi tidak cocok.' };
    }
    const key = username.toLowerCase();
    const users = getUsers();
    if (users[key]) {
      return { ok: false, error: 'Username sudah dipakai, coba yang lain.' };
    }
    const salt = randomSaltHex();
    const hash = await hashPassword(password, salt);
    users[key] = { username, salt, hash, createdAt: new Date().toISOString() };
    if (!writeJSON(USERS_KEY, users)) {
      return { ok: false, error: 'Gagal menyimpan akun (penyimpanan browser penuh).' };
    }
    localStorage.setItem(SESSION_KEY, key);
    return { ok: true, username };
  }

  async function loginUser(usernameRaw, password) {
    const username = (usernameRaw || '').trim();
    const key = username.toLowerCase();
    const users = getUsers();
    const record = users[key];
    if (!record) {
      return { ok: false, error: 'Username belum terdaftar.' };
    }
    const hash = await hashPassword(password, record.salt);
    if (hash !== record.hash) {
      return { ok: false, error: 'Kata sandi salah.' };
    }
    localStorage.setItem(SESSION_KEY, key);
    return { ok: true, username: record.username };
  }

  function logoutUser() {
    localStorage.removeItem(SESSION_KEY);
    document.documentElement.classList.remove('jp-logged-in');
    location.reload();
  }

  /* ---------------- photo history ---------------- */
  function downscaleForHistory(dataUrl, maxW) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const w = Math.max(1, Math.round(img.width * scale));
        const h = Math.max(1, Math.round(img.height * scale));
        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        try {
          resolve(c.toDataURL('image/jpeg', 0.9));
        } catch (e) {
          resolve(dataUrl);
        }
      };
      img.onerror = () => resolve(dataUrl);
      img.src = dataUrl;
    });
  }

  const KIND_LABELS = { strip: 'Strip Foto', grid: 'Grid 2x2', gif: 'GIF Animasi', ig: 'IG Post' };

  async function addHistoryEntry(dataUrl, filename, kind, frame) {
    const key = getCurrentUserKey();
    if (!key || !dataUrl) return;
    const thumb = await downscaleForHistory(dataUrl, 900);
    const store = getHistoryStore();
    const list = store[key] || [];
    list.unshift({
      id: 'h_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
      thumb,
      filename: filename || '',
      kind: kind || 'strip',
      frame: frame || 'nature',
      ts: Date.now()
    });
    store[key] = list.slice(0, MAX_HISTORY_PER_USER);
    if (!writeJSON(HISTORY_KEY, store)) {
      // storage full — drop oldest half and retry once
      store[key] = list.slice(0, Math.floor(MAX_HISTORY_PER_USER / 2));
      writeJSON(HISTORY_KEY, store);
    }
    renderHistoryModal();
  }

  function getMyHistory() {
    const key = getCurrentUserKey();
    if (!key) return [];
    const store = getHistoryStore();
    return store[key] || [];
  }

  function clearMyHistory() {
    const key = getCurrentUserKey();
    if (!key) return;
    const store = getHistoryStore();
    store[key] = [];
    writeJSON(HISTORY_KEY, store);
    renderHistoryModal();
  }

  function deleteHistoryEntry(id) {
    const key = getCurrentUserKey();
    if (!key) return;
    const store = getHistoryStore();
    store[key] = (store[key] || []).filter(item => item.id !== id);
    writeJSON(HISTORY_KEY, store);
    renderHistoryModal();
  }

  /* ---------------- UI wiring ---------------- */
  let authMode = 'login'; // 'login' | 'register'

  function $(id) { return document.getElementById(id); }

  function setAuthMode(mode) {
    authMode = mode;
    const isLogin = mode === 'login';
    $('auth-tab-login')?.classList.toggle('mode-active', isLogin);
    $('auth-tab-register')?.classList.toggle('mode-active', !isLogin);
    $('auth-confirm-wrap')?.classList.toggle('hidden', isLogin);
    $('auth-submit-btn').innerHTML = isLogin
      ? '<i class="fa-solid fa-right-to-bracket"></i><span>Masuk</span>'
      : '<i class="fa-solid fa-user-plus"></i><span>Daftar</span>';
    $('auth-switch-hint').innerHTML = isLogin
      ? 'Belum punya akun? <button type="button" onclick="JepretinAuth.setAuthMode(\'register\')" class="text-[var(--brass-soft)] font-bold hover:underline">Daftar di sini</button>'
      : 'Sudah punya akun? <button type="button" onclick="JepretinAuth.setAuthMode(\'login\')" class="text-[var(--brass-soft)] font-bold hover:underline">Masuk di sini</button>';
    setAuthError('');
    clearAllHints();
    if (mode === 'register') validateUsernameLive();
  }

  function setAuthError(msg) {
    const el = $('auth-error');
    if (!el) return;
    if (!msg) { el.classList.add('hidden'); el.textContent = ''; return; }
    el.textContent = msg;
    el.classList.remove('hidden');
    el.classList.remove('auth-shake');
    void el.offsetWidth;
    el.classList.add('auth-shake');
  }

  function revealLandingAfterAuth() {
    const authScreen = $('auth-screen');
    const landing = $('landing-screen');
    if (authScreen) authScreen.classList.add('auth-fade-out');
    if (landing) landing.classList.add('play-intro');
    setTimeout(() => { if (authScreen) authScreen.style.display = 'none'; }, 480);
  }

  function updateIdentityUI() {
    const user = getCurrentUser();
    const name = user ? user.username : '';
    const greetEl = $('landing-greet');
    const greetTextEl = $('landing-greet-text');
    if (greetEl) {
      if (greetTextEl) greetTextEl.textContent = name ? `Halo, ${name} \u2014 mesin siap buat kamu!` : '';
      greetEl.classList.toggle('hidden', !name);
      greetEl.classList.toggle('flex', !!name);
    }
    const logoutHint = $('landing-logout-hint');
    if (logoutHint) logoutHint.classList.toggle('hidden', !name);
    const badgeName = $('user-badge-name');
    if (badgeName) badgeName.textContent = name;
    const badge = $('user-badge');
    if (badge) {
      badge.classList.toggle('hidden', !name);
      badge.classList.toggle('flex', !!name);
    }
  }

  function togglePasswordVisibility(inputId, btnEl) {
    const input = $(inputId);
    if (!input) return;
    const showing = input.type === 'text';
    input.type = showing ? 'password' : 'text';
    const icon = btnEl.querySelector('i');
    if (icon) {
      icon.classList.toggle('fa-eye', showing);
      icon.classList.toggle('fa-eye-slash', !showing);
    }
  }

  /* ---------------- live (real-time) validation ---------------- */
  function setHint(id, msg, tone) {
    const el = $(id);
    if (!el) return;
    if (!msg) {
      el.textContent = '';
      el.classList.add('hidden');
      return;
    }
    el.textContent = msg;
    el.classList.remove('hidden');
    el.classList.remove('text-emerald-400', 'text-[var(--crimson-soft)]', 'text-[#6b6152]');
    el.classList.add(tone === 'ok' ? 'text-emerald-400' : tone === 'bad' ? 'text-[var(--crimson-soft)]' : 'text-[#6b6152]');
  }

  function validateUsernameLive() {
    const el = $('auth-username');
    if (!el) return true;
    const val = el.value.trim();
    if (!val) { setHint('auth-username-hint', ''); return false; }
    if (!USERNAME_RE.test(val)) {
      setHint('auth-username-hint', 'Username 3-16 karakter, huruf/angka/underscore saja.', 'bad');
      return false;
    }
    if (authMode === 'register' && getUsers()[val.toLowerCase()]) {
      setHint('auth-username-hint', 'Username sudah dipakai, coba yang lain.', 'bad');
      return false;
    }
    setHint('auth-username-hint', authMode === 'register' ? 'Username tersedia.' : '', 'ok');
    return true;
  }

  function validatePasswordLive() {
    const el = $('auth-password');
    if (!el) return true;
    const val = el.value;
    if (!val) { setHint('auth-password-hint', ''); return false; }
    if (val.length < 4) {
      setHint('auth-password-hint', `Minimal 4 karakter (${val.length}/4).`, 'bad');
      return false;
    }
    setHint('auth-password-hint', authMode === 'register' ? 'Panjang oke.' : '', 'ok');
    return true;
  }

  function validateConfirmLive() {
    if (authMode !== 'register') { setHint('auth-confirm-hint', ''); return true; }
    const pw = $('auth-password')?.value || '';
    const val = $('auth-password-confirm')?.value || '';
    if (!val) { setHint('auth-confirm-hint', ''); return false; }
    if (val !== pw) {
      setHint('auth-confirm-hint', 'Belum sama dengan kata sandi di atas.', 'bad');
      return false;
    }
    setHint('auth-confirm-hint', 'Cocok!', 'ok');
    return true;
  }

  function clearAllHints() {
    ['auth-username-hint', 'auth-password-hint', 'auth-confirm-hint'].forEach(id => setHint(id, ''));
  }

  function focusUsernameIfVisible() {
    if (isLoggedIn()) return;
    const input = $('auth-username');
    if (input) input.focus({ preventScroll: true });
  }

  function watchSplashAndFocus() {
    const splash = $('splash-screen');
    if (!splash) { focusUsernameIfVisible(); return; }
    if (splash.style.display === 'none') { focusUsernameIfVisible(); return; }
    const obs = new MutationObserver(() => {
      if (splash.style.display === 'none') {
        focusUsernameIfVisible();
        obs.disconnect();
      }
    });
    obs.observe(splash, { attributes: true, attributeFilter: ['style'] });
  }

  async function handleAuthSubmit(e) {
    e.preventDefault();
    const btn = $('auth-submit-btn');
    const username = $('auth-username').value;
    const password = $('auth-password').value;
    const confirm = $('auth-password-confirm').value;
    btn.disabled = true;
    btn.classList.add('opacity-60');
    try {
      const result = authMode === 'login'
        ? await loginUser(username, password)
        : await registerUser(username, password, confirm);
      if (!result.ok) {
        setAuthError(result.error);
        return;
      }
      document.documentElement.classList.add('jp-logged-in');
      updateIdentityUI();
      revealLandingAfterAuth();
      if (typeof showToast === 'function') {
        showToast(`Halo, ${result.username}! ${authMode === 'register' ? 'Akun dibuat' : 'Berhasil masuk'}.`, '👋');
      }
    } finally {
      btn.disabled = false;
      btn.classList.remove('opacity-60');
    }
  }

  /* ---------------- history modal ---------------- */
  function openHistoryModal() {
    renderHistoryModal();
    const modal = $('history-modal');
    if (!modal) return;
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
  function closeHistoryModal() {
    const modal = $('history-modal');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }

  function timeAgoLabel(ts) {
    const d = new Date(ts);
    return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' }) + ' \u00b7 ' +
      d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  }

  function renderHistoryModal() {
    const grid = $('history-modal-grid');
    const empty = $('history-empty-state');
    if (!grid) return;
    const items = getMyHistory();
    grid.innerHTML = '';
    if (empty) {
      empty.classList.toggle('hidden', items.length > 0);
      empty.classList.toggle('flex', items.length === 0);
    }
    items.forEach((item, idx) => {
      const card = document.createElement('div');
      card.className = 'relative rounded-xl overflow-hidden border border-[var(--line)] bg-[#ffffff] group card-rise-in';
      card.style.setProperty('--i', idx);
      card.innerHTML = `
        <img src="${item.thumb}" alt="${KIND_LABELS[item.kind] || 'Foto'}" class="w-full aspect-[3/4] object-cover">
        <div class="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent px-2 pt-4 pb-1.5">
          <p class="text-[10px] font-bold text-[#f3e6c7] leading-tight">${KIND_LABELS[item.kind] || 'Foto'}</p>
          <p class="text-[9px] text-[#d6c6a0]">${timeAgoLabel(item.ts)}</p>
        </div>
        <div class="absolute top-1.5 right-1.5 flex gap-1 opacity-0 group-hover:opacity-100 transition">
          <button onclick="JepretinAuth.openMockupModal('${item.id}')" title="Lihat POV" class="w-7 h-7 flex items-center justify-center rounded-full bg-black/60 text-white hover:text-[var(--brass-soft)]">
            <i class="fa-solid fa-wand-magic-sparkles text-[11px]"></i>
          </button>
          <a href="${item.thumb}" download="${item.filename || 'jepretin.jpg'}" title="Unduh" class="w-7 h-7 flex items-center justify-center rounded-full bg-black/60 text-white hover:text-[var(--brass-soft)]">
            <i class="fa-solid fa-download text-[11px]"></i>
          </a>
          <button onclick="JepretinAuth.deleteHistoryEntry('${item.id}')" title="Hapus" class="w-7 h-7 flex items-center justify-center rounded-full bg-black/60 text-white hover:text-[var(--crimson-soft)]">
            <i class="fa-solid fa-trash text-[11px]"></i>
          </button>
        </div>`;
      grid.appendChild(card);
    });
  }

  /* ---------------- mockup POV (latar bertema, mengikuti bingkai foto asli) ---------------- */
  let mockupItem = null;
  let mockupImgObj = null;
  let mockupAnimRAF = null;
  let mockupAnimStartTs = 0;

  // Ikon asli app (bukan cuma teks) dipakai sebagai identitas di puncak POV.
  // Dimuat sekali & di-cache; kalau frame animasi pertama berjalan sebelum
  // gambar ini selesai load, drawBrandIdentity() otomatis melewatinya dulu.
  let brandIconImg = null;
  function getBrandIconImg() {
    if (!brandIconImg) {
      brandIconImg = new Image();
      brandIconImg.src = JEPRETIN_ICON_DATA_URI; // data URI, bukan file terpisah — lihat catatan di atas
    }
    return brandIconImg;
  }

  // FRAME_THEMES didefinisikan di app.js (di scope global yang sama karena
  // sama-sama classic <script>). Fallback dipakai kalau app.js belum/tidak sempat load.
  function getFrameThemeCfg(frameId) {
    const themes = (typeof FRAME_THEMES !== 'undefined') ? FRAME_THEMES : null;
    if (themes && themes[frameId]) return themes[frameId];
    if (themes && themes.nature) return themes.nature;
    return {
      accent: '#c9a04a', stampBg: '#fdf8ec', stampFg: '#6b5636',
      brandText: 'JEPRETIN', tagline: 'Captured moments, framed with love',
      stickers: ['✨', '🌿', '📸']
    };
  }

  // Faktor perbesaran resolusi kanvas POV — dulu kanvas ini punya ukuran piksel
  // asli cuma 760x1000, jadi HANYA sebesar itu juga hasil downloadnya (termasuk
  // teks brand yang digambar langsung di kanvas ini). Dengan menaikkan ukuran
  // piksel asli kanvas (bukan cuma ukuran tampilannya di CSS) lalu men-scale
  // context menggambar mengikuti faktor yang sama, semua yang digambar di sini
  // otomatis jadi tajam/HD saat diunduh, seperti kanvas "retina".
  const MOCKUP_SCALE = 3;
  function ensureMockupCanvasResolution() {
    const canvas = $('mockup-canvas');
    if (!canvas) return;
    const baseW = parseInt(canvas.dataset.baseW || canvas.width, 10) || 760;
    const baseH = parseInt(canvas.dataset.baseH || canvas.height, 10) || 1000;
    const targetW = baseW * MOCKUP_SCALE, targetH = baseH * MOCKUP_SCALE;
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
  }

  function openMockupModal(id) {
    const item = getMyHistory().find((i) => i.id === id);
    if (!item) return;
    mockupItem = item;
    const modal = $('mockup-modal');
    if (modal) { modal.classList.remove('hidden'); modal.classList.add('flex'); }
    ensureMockupCanvasResolution();
    getBrandIconImg(); // mulai preload lebih awal supaya siap saat frame pertama
    const img = new Image();
    img.onload = () => { mockupImgObj = img; startMockupAnimation(); };
    img.src = item.thumb;
  }

  function closeMockupModal() {
    const modal = $('mockup-modal');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
    stopMockupAnimation();
  }

  // Preview POV di-render sebagai loop animasi (bukan gambar diam) selama
  // modal terbuka — identitas brand di puncak berdenyut/mengambang/berkilau.
  // Loop otomatis berhenti saat modal ditutup supaya tidak boros resource.
  function startMockupAnimation() {
    stopMockupAnimation();
    mockupAnimStartTs = performance.now();
    const loop = (now) => {
      renderMockupCanvas((now - mockupAnimStartTs) / 1000);
      mockupAnimRAF = requestAnimationFrame(loop);
    };
    mockupAnimRAF = requestAnimationFrame(loop);
  }

  function stopMockupAnimation() {
    if (mockupAnimRAF !== null) {
      cancelAnimationFrame(mockupAnimRAF);
      mockupAnimRAF = null;
    }
  }


  function downloadMockupResult() {
    const canvas = $('mockup-canvas');
    if (!canvas || !mockupItem) return;
    try {
      // Render ulang satu frame BERSIH (tanpa bob/pulse/kilau cahaya) khusus
      // untuk file yang diunduh, lepas dari posisi animasi live yang sedang
      // berjalan di layar. Animasi live tetap lanjut normal di frame
      // requestAnimationFrame berikutnya — cuma dataURL di bawah ini yang
      // memakai frame statis tersebut.
      renderMockupCanvas(0, true);
      const label = (mockupItem.frame || 'jepretin').toLowerCase().replace(/[^a-z0-9]+/g, '-');
      const a = document.createElement('a');
      a.download = `jepretin-pov-${label}-${Date.now()}.png`;
      a.href = canvas.toDataURL('image/png', 0.95);
      a.click();
    } catch (e) {
      // Jaring pengaman: kalau suatu saat canvas ke-taint lagi (mis. ada
      // gambar lintas-asal baru yang ditambahkan tanpa data URI), user
      // tetap dapat notifikasi jelas alih-alih tombol yang diam saja.
      if (typeof showToast === 'function') {
        showToast('Gagal mengunduh POV, coba lagi ya.', '⚠️');
      } else {
        alert('Gagal mengunduh POV. Coba lagi ya.');
      }
    }
  }

  function roundRectPath(ctx, x, y, w, h, r) {
    if (typeof r === 'number') r = { tl: r, tr: r, br: r, bl: r };
    ctx.beginPath();
    ctx.moveTo(x + r.tl, y);
    ctx.lineTo(x + w - r.tr, y);
    ctx.arcTo(x + w, y, x + w, y + r.tr, r.tr);
    ctx.lineTo(x + w, y + h - r.br);
    ctx.arcTo(x + w, y + h, x + w - r.br, y + h, r.br);
    ctx.lineTo(x + r.bl, y + h);
    ctx.arcTo(x, y + h, x, y + h - r.bl, r.bl);
    ctx.lineTo(x, y + r.tl);
    ctx.arcTo(x, y, x + r.tl, y, r.tl);
    ctx.closePath();
  }

  // Menggambar strip foto (dengan mat/kartu terangkat + bayangan) yang pas
  // di dalam kotak maksimal maxW x maxH, dirotasi sejumlah `rotation` radian.
  // opts.matColor & opts.accentBorder membuat kartu ini ikut warna tema
  // (bukan selalu krem terang) supaya strip terlihat "ditempel" di atas
  // backdrop bertema, bukan sekadar mengambang.
  function drawStripImage(ctx, img, cx, cy, maxW, maxH, rotation, opts) {
    const ratio = img.height / img.width;
    let w = maxW, h = w * ratio;
    if (h > maxH) { h = maxH; w = h / ratio; }
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rotation);
    if (opts && opts.shadow) {
      ctx.shadowColor = opts.shadowColor || 'rgba(20,15,5,0.45)';
      ctx.shadowBlur = opts.shadowBlur || 32;
      ctx.shadowOffsetY = opts.shadowOffsetY || 18;
    }
    ctx.fillStyle = (opts && opts.matColor) || '#fdfaf2';
    roundRectPath(ctx, -w / 2 - 7, -h / 2 - 7, w + 14, h + 14, 7);
    ctx.fill();
    ctx.shadowColor = 'transparent';
    if (opts && opts.accentBorder) {
      ctx.save();
      ctx.globalAlpha = 0.55;
      ctx.strokeStyle = opts.accentBorder;
      ctx.lineWidth = 2;
      roundRectPath(ctx, -w / 2 - 6, -h / 2 - 6, w + 12, h + 12, 6);
      ctx.stroke();
      ctx.restore();
    }
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
    return { w, h };
  }

  // Latar belakang POV bertema: memakai sistem backdrop "print-shop quality"
  // yang sama dengan hasil download strip (glow lembut + grain halus +
  // vignette), lalu foto strip ditempel di atasnya seperti cetakan asli,
  // ditutup dengan susunan brand yang sama (eyebrow label, nama brand, seal,
  // baris meta) — supaya preview POV terlihat konsisten & profesional,
  // otomatis mengikuti warna & motif bingkai yang dipakai saat foto diambil.
  // Identitas brand animasi di puncak POV: ikon asli app + wordmark, dengan
  // glow yang berdenyut, ikon yang mengambang & sedikit berayun, plus kilau
  // cahaya yang menyapu tulisan secara berkala — bukan teks statis.
  function drawBrandIdentity(ctx, W, accent, ink, tSec, staticMode) {
    const withAlpha = (typeof hexToRgba === 'function') ? hexToRgba : (hex) => hex;
    const icon = getBrandIconImg();
    const hasIcon = !!(icon && icon.complete && icon.naturalWidth > 0);
    const cx = W / 2, barY = 46;
    // staticMode dipakai khusus saat merender frame yang akan DI-UNDUH:
    // tanpa bob/pulse/kilau, supaya file PNG selalu bersih & konsisten,
    // tidak pernah "membekukan" sapuan cahaya di tengah jalan (yang kalau
    // ter-capture malah terlihat seperti noda/glitch, bukan efek premium).
    const bob = staticMode ? 0 : Math.sin(tSec * 1.6) * 3;      // ikon mengambang naik-turun pelan
    const pulse = staticMode ? 0.5 : (0.5 + 0.5 * Math.sin(tSec * 1.8)); // 0..1, buat glow berdenyut

    // Glow lembut yang berdenyut di belakang identitas.
    ctx.save();
    const haloR = 66 + pulse * 12;
    const halo = ctx.createRadialGradient(cx, barY, 0, cx, barY, haloR);
    halo.addColorStop(0, withAlpha(accent, 0.24 + pulse * 0.12));
    halo.addColorStop(1, withAlpha(accent, 0));
    ctx.fillStyle = halo;
    ctx.fillRect(cx - haloR, barY - haloR, haloR * 2, haloR * 2);
    ctx.restore();

    ctx.save();
    ctx.font = "800 22px 'Plus Jakarta Sans', sans-serif";
    const wordmark = 'JEPRETIN';
    const wmWidth = ctx.measureText(wordmark).width;
    const iconSize = 28, iconGap = 10;
    const groupW = wmWidth + (hasIcon ? iconSize + iconGap : 0);
    let x = cx - groupW / 2;

    if (hasIcon) {
      ctx.save();
      ctx.translate(x + iconSize / 2, barY + bob);
      ctx.rotate(staticMode ? 0 : Math.sin(tSec * 1.6) * 0.06); // sedikit berayun kayak gantungan
      ctx.drawImage(icon, -iconSize / 2, -iconSize / 2, iconSize, iconSize);
      ctx.restore();
      x += iconSize + iconGap;
    }

    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = ink;
    ctx.fillText(wordmark, x, barY + bob * 0.4);

    // Kilau cahaya yang menyapu wordmark secara berkala, seperti efek
    // "shine" pada logo premium — bukan cuma teks diam di tempat.
    // HANYA untuk preview live di layar. Frame yang dipakai untuk file
    // yang diunduh selalu dirender dengan staticMode=true di
    // downloadMockupResult(), jadi efek ini tidak pernah ikut ter-simpan
    // ke PNG (sebelumnya inilah yang terlihat seperti "kilatan cahaya"
    // mengganggu pada hasil unduhan).
    if (!staticMode) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(x - 2, barY - 18, wmWidth + 4, 36);
      ctx.clip();
      const sweepPeriod = 2.6;
      const sweepT = (tSec % sweepPeriod) / sweepPeriod;
      const sweepX = x - wmWidth * 0.5 + sweepT * (wmWidth * 2);
      const shine = ctx.createLinearGradient(sweepX - 22, 0, sweepX + 22, 0);
      shine.addColorStop(0, 'rgba(255,255,255,0)');
      shine.addColorStop(0.5, 'rgba(255,255,255,0.6)');
      shine.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = shine;
      ctx.fillRect(x - 2, barY - 18, wmWidth + 4, 36);
      ctx.restore();
    }

    ctx.restore();

    // Sepasang siku hias kecil mengapit wordmark — biar identitas di puncak
    // terasa seperti kop/masthead yang dirancang, bukan cuma logo sendirian
    // mengambang di ruang kosong.
    ctx.save();
    ctx.strokeStyle = withAlpha(accent, 0.55);
    ctx.lineWidth = 1.5;
    const flourishGap = groupW / 2 + 22;
    [-1, 1].forEach((dir) => {
      const fx = cx + dir * flourishGap;
      ctx.beginPath();
      ctx.moveTo(fx, barY + bob * 0.4 - 7); ctx.lineTo(fx + dir * 15, barY + bob * 0.4);
      ctx.lineTo(fx, barY + bob * 0.4 + 7);
      ctx.stroke();
    });
    ctx.restore();

    // Subjudul kecil di bawah wordmark (tagline resmi brand) — supaya
    // puncak halaman tidak cuma menampilkan nama, tapi juga sedikit
    // identitas tambahan seperti pada logo aslinya.
    const subtitleY = barY + 30;
    ctx.save();
    ctx.font = "600 13px 'Plus Jakarta Sans', sans-serif";
    ctx.fillStyle = withAlpha(ink, 0.62);
    ctx.textAlign = 'center';
    const subtitle = 'JEPRET · GAYA · SIMPAN';
    if (typeof drawTrackedText === 'function') drawTrackedText(ctx, subtitle, cx, subtitleY, 2.4);
    else ctx.fillText(subtitle, cx, subtitleY);
    ctx.restore();

    // Garis pemisah dekoratif (garis–belah ketupat–garis) menutup blok
    // identitas dengan tegas, sekaligus jadi penanda jarak yang jelas
    // sebelum strip foto mulai di bawahnya — tidak lagi mepet ke atas.
    const dividerY = subtitleY + 20;
    ctx.save();
    ctx.strokeStyle = withAlpha(accent, 0.55);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx - 74, dividerY); ctx.lineTo(cx - 8, dividerY);
    ctx.moveTo(cx + 8, dividerY); ctx.lineTo(cx + 74, dividerY);
    ctx.stroke();
    ctx.save();
    ctx.translate(cx, dividerY);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = accent;
    ctx.fillRect(-4, -4, 8, 8);
    ctx.restore();
    ctx.restore();

    // Batas bawah seluruh blok identitas — dipakai si pemanggil untuk
    // menghitung jarak aman sebelum menaruh strip foto.
    return dividerY + 30;
  }

  function drawThemedGalleryBackground(ctx, W, H, img, frameId, tSec, staticMode) {
    const cfg = getFrameThemeCfg(frameId);
    const accent = cfg.accent || '#c9a04a';

    // app.js (dimuat di halaman yang sama) menyediakan fungsi/warna tema yang
    // lebih kaya; typeof-check ini cuma jaring pengaman kalau suatu saat file
    // itu gagal/telat dimuat, bukan alur normal.
    const hasThemeEngine = typeof paintThemedBackground === 'function' && typeof DARK_FRAME_THEMES !== 'undefined';
    const isDark = hasThemeEngine ? DARK_FRAME_THEMES.has(frameId) : true;
    const paper = isDark ? '#1c1e17' : '#f7f2e8';
    const ink = isDark ? '#ffffff' : '#241f16';
    const inkMuted = isDark ? 'rgba(237,227,208,0.62)' : 'rgba(26,28,20,0.58)';
    const inkFaint = isDark ? 'rgba(237,227,208,0.4)' : 'rgba(26,28,20,0.34)';
    const withAlpha = (typeof hexToRgba === 'function') ? hexToRgba : (hex, a) => hex;
    const pad = 56;

    if (hasThemeEngine) {
      // Backdrop studio hidup: base kertas + glow warna aksen + grain diagonal
      // halus + vignette — identik dengan yang dipakai di hasil download.
      paintThemedBackground(ctx, paper, accent, W, H, isDark);
    } else {
      const grad = ctx.createLinearGradient(0, 0, W, H);
      grad.addColorStop(0, paper);
      grad.addColorStop(1, accent);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
    }

    // Bingkai kartu penuh di tepi — garis ganda tipis warna aksen, biar
    // seluruh kanvas terasa seperti satu produk cetak yang dirancang, bukan
    // kanvas kosong dengan beberapa elemen mengambang di tengah.
    ctx.save();
    ctx.strokeStyle = withAlpha(accent, isDark ? 0.55 : 0.4);
    ctx.lineWidth = 1.5;
    if (typeof roundRectPath === 'function') {
      roundRectPath(ctx, 18, 18, W - 36, H - 36, 18);
      ctx.stroke();
    }
    ctx.globalAlpha = 0.5;
    ctx.lineWidth = 1;
    if (typeof roundRectPath === 'function') {
      roundRectPath(ctx, 24, 24, W - 48, H - 48, 14);
      ctx.stroke();
    }
    ctx.restore();

    // Identitas brand di puncak — logo asli app + wordmark, subjudul, dan
    // garis hias penutup, bukan cuma teks nama doang: ada glow yang
    // berdenyut, ikon yang mengambang pelan, dan kilau cahaya yang menyapu
    // tulisan. Animasi berjalan selama modal terbuka. Nilai baliknya dipakai
    // untuk menghitung jarak aman sebelum strip foto, supaya strip tidak
    // mepet ke bagian atas.
    const identityBottom = drawBrandIdentity(ctx, W, accent, ink, tSec || 0, !!staticMode);

    // Ikon khas tema digambar raksasa & sangat transparan sebagai watermark
    // latar — mengisi ruang kosong dengan personalitas tema tanpa berisik,
    // seperti motif timbul di kertas kop surat.
    const wmGlyph = (cfg.stickers && cfg.stickers[0]) || cfg.emoji || '✨';
    ctx.save();
    ctx.globalAlpha = isDark ? 0.1 : 0.14;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = (W * 0.62) + 'px sans-serif';
    ctx.translate(W / 2, H * 0.34);
    ctx.rotate(-0.06);
    ctx.fillText(wmGlyph, 0, 0);
    ctx.restore();

    // Tekstur titik halus menyebar di seluruh kanvas — memberi rasa kertas
    // bertekstur di area-area kosong, senada dengan grain diagonal di atas.
    ctx.save();
    ctx.globalAlpha = isDark ? 0.16 : 0.1;
    ctx.fillStyle = accent;
    for (let y = pad * 0.5; y < H - pad * 0.3; y += 30) {
      for (let x = pad * 0.5; x < W - pad * 0.3; x += 30) {
        ctx.beginPath();
        ctx.arc(x, y, 1.1, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
    ctx.save();
    ctx.strokeStyle = withAlpha(accent, 0.5);
    ctx.lineWidth = 2;
    [[pad * 0.55, pad * 0.72], [W - pad * 0.55, pad * 0.72]].forEach(([x, y], i) => {
      const dir = i === 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(x, y); ctx.lineTo(x + dir * 14, y);
      ctx.moveTo(x, y - 7); ctx.lineTo(x, y + 7);
      ctx.stroke();
    });
    ctx.restore();

    // Motif dekoratif khas tema di sisi kiri/kanan (daun, sirkuit, sparkle,
    // dst.) — sentuhan personalitas yang sama seperti di margin strip asli.
    if (typeof drawThemeBorderDecoration === 'function') {
      drawThemeBorderDecoration(ctx, cfg, W, H, pad);
    }

    // Dua strip foto yang sama ditempel berdampingan, sedikit terbuka
    // (fan-out) ke kiri & kanan — gaya "kembar cetakan" seperti referensi,
    // bukan cuma satu strip di tengah.
    const footerH = 340;
    const photoTop = Math.max(pad * 1.35, identityBottom + 34);
    const photoAreaH = H - footerH - photoTop;
    const cy = photoTop + photoAreaH / 2;
    const gapBetween = 26;
    const panelW = (W - pad * 2 - gapBetween) / 2;
    const cx1 = pad + panelW / 2;
    const cx2 = W - pad - panelW / 2;

    // Spotlight lembut menaungi kedua strip sekaligus.
    ctx.save();
    const spot = ctx.createRadialGradient(W / 2, cy, 0, W / 2, cy, W * 0.55);
    spot.addColorStop(0, withAlpha(accent, isDark ? 0.26 : 0.15));
    spot.addColorStop(1, withAlpha(accent, 0));
    ctx.fillStyle = spot;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    const stripOpts = {
      shadow: true, shadowBlur: 36, shadowOffsetY: 20,
      matColor: isDark ? '#14160f' : '#ffffff',
      accentBorder: accent
    };
    drawStripImage(ctx, img, cx1, cy, panelW - 16, photoAreaH - 20, -0.11, stripOpts);
    drawStripImage(ctx, img, cx2, cy, panelW - 16, photoAreaH - 20, 0.11, stripOpts);

    // ---- Susunan brand di bawah foto: eyebrow, nama brand, tagline, seal ----
    const footerTop = photoTop + photoAreaH + 30;

    ctx.textAlign = 'center';
    ctx.font = "700 19px 'Plus Jakarta Sans', sans-serif";
    ctx.fillStyle = accent;
    const eyebrow = (cfg.subText || cfg.label || 'JEPRETIN').toUpperCase();
    if (typeof drawTrackedText === 'function') drawTrackedText(ctx, eyebrow, W / 2, footerTop, 3);
    else ctx.fillText(eyebrow, W / 2, footerTop);

    ctx.font = "800 40px 'Plus Jakarta Sans', sans-serif";
    ctx.fillStyle = ink;
    ctx.fillText(cfg.brandText || 'JEPRETIN', W / 2, footerTop + 46);

    ctx.strokeStyle = withAlpha(accent, 0.5);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(W / 2 - 58, footerTop + 60);
    ctx.lineTo(W / 2 + 58, footerTop + 60);
    ctx.stroke();

    ctx.font = "500 16px 'Plus Jakarta Sans', sans-serif";
    ctx.fillStyle = inkMuted;
    const tagline = cfg.tagline || 'jepretin.app';
    if (typeof wrapCenteredText === 'function') wrapCenteredText(ctx, tagline, W / 2, footerTop + 88, W - pad * 2.4, 21);
    else ctx.fillText(tagline, W / 2, footerTop + 88);

    // ---- Ruang dekoratif bertema di bawah tagline ----
    // Sebelumnya footer cuma eyebrow + nama brand + tagline lalu langsung
    // seal — terasa kosong/polos. Kartu bermotif tema ini mengisi "napas"
    // itu dengan sentuhan visual yang mengikuti tema aktif, jadi area ini
    // tidak lagi hanya teks & logo.
    const noteW = W - pad * 2.2, noteH = 78;
    const noteX = W / 2 - noteW / 2, noteY = footerTop + 118;
    ctx.save();
    ctx.setLineDash([6, 6]);
    ctx.lineWidth = 1.4;
    ctx.strokeStyle = withAlpha(accent, 0.4);
    if (typeof roundRectPath === 'function') {
      roundRectPath(ctx, noteX, noteY, noteW, noteH, 14);
      ctx.stroke();
    }
    ctx.setLineDash([]);
    ctx.restore();

    const noteGlyphs = (cfg.stickers && cfg.stickers.length) ? cfg.stickers.slice(0, 5) : ['✨'];
    ctx.save();
    ctx.font = '26px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.globalAlpha = 0.85;
    const glyphStep = noteW / (noteGlyphs.length + 1);
    noteGlyphs.forEach((glyph, i) => {
      ctx.save();
      ctx.translate(noteX + glyphStep * (i + 1), noteY + noteH / 2);
      ctx.rotate((i % 2 === 0 ? -1 : 1) * 0.12);
      ctx.fillText(glyph, 0, 0);
      ctx.restore();
    });
    ctx.restore();

    // Seal bundar kecil, restrained — ganti lingkaran wreath lama.
    const sealR = 25, sealX = pad * 0.85, sealY = H - 52;
    ctx.save();
    ctx.translate(sealX, sealY);
    ctx.rotate(-0.08);
    ctx.beginPath(); ctx.arc(0, 0, sealR, 0, Math.PI * 2);
    ctx.fillStyle = withAlpha(accent, isDark ? 0.18 : 0.1);
    ctx.fill();
    ctx.lineWidth = 1.4;
    ctx.strokeStyle = accent;
    ctx.beginPath(); ctx.arc(0, 0, sealR, 0, Math.PI * 2); ctx.stroke();
    ctx.font = "700 9px 'Fira Code', monospace";
    ctx.fillStyle = ink;
    ctx.textAlign = 'center';
    (cfg.stampText || cfg.label || 'JEPRETIN').toUpperCase().split(' ').forEach((word, i, arr) => {
      ctx.fillText(word, 0, (i - (arr.length - 1) / 2) * 10 + 3);
    });
    ctx.restore();

    // Baris meta ala struk kasir booth — tanggal & jam foto ini diambil.
    const shotDate = new Date(mockupItem && mockupItem.ts ? mockupItem.ts : Date.now());
    const dateStr = shotDate.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
    const timeStr = shotDate.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    ctx.textAlign = 'right';
    ctx.font = "600 14px 'Fira Code', monospace";
    ctx.fillStyle = inkFaint;
    ctx.fillText(`POV · ${dateStr} · ${timeStr}`, W - pad * 0.5, H - 48);

    ctx.textAlign = 'center';
    ctx.font = "600 11px sans-serif";
    ctx.fillStyle = inkFaint;
    ctx.fillText('jepretin.app', W / 2, H - 18);
  }

  function renderMockupCanvas(tSec, staticMode) {
    const canvas = $('mockup-canvas');
    if (!canvas || !mockupImgObj || !mockupItem) return;
    const ctx = canvas.getContext('2d');
    const W = parseInt(canvas.dataset.baseW || 760, 10);
    const H = parseInt(canvas.dataset.baseH || 1000, 10);
    ctx.setTransform(MOCKUP_SCALE, 0, 0, MOCKUP_SCALE, 0, 0);
    ctx.clearRect(0, 0, W, H);
    drawThemedGalleryBackground(ctx, W, H, mockupImgObj, mockupItem.frame, tSec || 0, staticMode);
  }

  /* ---------------- boot ---------------- */
  function boot() {
    if (isLoggedIn()) document.documentElement.classList.add('jp-logged-in');
    updateIdentityUI();
    const form = $('auth-form');
    if (form) form.addEventListener('submit', handleAuthSubmit);
    $('auth-username')?.addEventListener('input', validateUsernameLive);
    $('auth-password')?.addEventListener('input', () => { validatePasswordLive(); validateConfirmLive(); });
    $('auth-password-confirm')?.addEventListener('input', validateConfirmLive);
    setAuthMode('login');
    watchSplashAndFocus();
    // Returning logged-in users: auth-screen is hidden via the .jp-logged-in
    // CSS rule, so the splash reveal lands straight on the landing screen.
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }

  /* ---------------- public API ---------------- */
  window.JepretinAuth = {
    isLoggedIn, getCurrentUser, logoutUser, setAuthMode,
    addHistoryEntry, getMyHistory, clearMyHistory, deleteHistoryEntry,
    openHistoryModal, closeHistoryModal, togglePasswordVisibility,
    openMockupModal, closeMockupModal, downloadMockupResult
  };
  // Convenience globals used directly by onclick="" attributes in index.html
  window.logoutUser = logoutUser;
  window.openHistoryModal = openHistoryModal;
  window.closeHistoryModal = closeHistoryModal;
  window.clearMyHistory = clearMyHistory;
})();